Proximity.ILP.feasible.eq_1.type:
∀ {n : Nat} (P : Proximity.ILP n) (x : Fin n → Real),
  @Eq.{1} Prop (@Proximity.ILP.feasible n P x)
    (And
      (∀ (r : Proximity.Row n),
        @Membership.mem.{0, 0} (Proximity.Row n) (List.{0} (Proximity.Row n))
            (@List.instMembership.{0} (Proximity.Row n)) (@Proximity.ILP.equalities n P) r →
          @Eq.{1} Real (@Proximity.Row.eval n r x) (@Int.cast.{0} Real Real.instIntCast (@Proximity.Row.rhs n r)))
      (And
        (∀ (r : Proximity.Row n),
          @Membership.mem.{0, 0} (Proximity.Row n) (List.{0} (Proximity.Row n))
              (@List.instMembership.{0} (Proximity.Row n)) (@Proximity.ILP.inequalities n P) r →
            @LE.le.{0} Real Real.instLE (@Proximity.Row.eval n r x)
              (@Int.cast.{0} Real Real.instIntCast (@Proximity.Row.rhs n r)))
        (And
          (∀ (i : Fin n) (b : Int),
            @Eq.{1} (Option.{0} Int) (@Proximity.ILP.lower n P i) (@Option.some.{0} Int b) →
              @LE.le.{0} Real Real.instLE (@Int.cast.{0} Real Real.instIntCast b) (x i))
          (∀ (i : Fin n) (b : Int),
            @Eq.{1} (Option.{0} Int) (@Proximity.ILP.upper n P i) (@Option.some.{0} Int b) →
              @LE.le.{0} Real Real.instLE (x i) (@Int.cast.{0} Real Real.instIntCast b)))))

Proximity.ILP.mk.inj.type:
∀ {n : Nat} {equalities inequalities : List.{0} (Proximity.Row n)} {lower upper : Fin n → Option.{0} Int}
  {cost : Fin n → Int} {constant : Int} {equalities_1 inequalities_1 : List.{0} (Proximity.Row n)}
  {lower_1 upper_1 : Fin n → Option.{0} Int} {cost_1 : Fin n → Int} {constant_1 : Int},
  @Eq.{1} (Proximity.ILP n) (@Proximity.ILP.mk n equalities inequalities lower upper cost constant)
      (@Proximity.ILP.mk n equalities_1 inequalities_1 lower_1 upper_1 cost_1 constant_1) →
    And (@Eq.{1} (List.{0} (Proximity.Row n)) equalities equalities_1)
      (And (@Eq.{1} (List.{0} (Proximity.Row n)) inequalities inequalities_1)
        (And (@Eq.{1} (Fin n → Option.{0} Int) lower lower_1)
          (And (@Eq.{1} (Fin n → Option.{0} Int) upper upper_1)
            (And (@Eq.{1} (Fin n → Int) cost cost_1) (@Eq.{1} Int constant constant_1)))))

Proximity.Row.eval.eq_1.type:
∀ {n : Nat} (r : Proximity.Row n) (x : Fin n → Real),
  @Eq.{1} Real (@Proximity.Row.eval n r x)
    (∑ i,
      @HMul.hMul.{0, 0, 0} Real Real Real (@instHMul.{0} Real Real.instMul)
        (@Int.cast.{0} Real Real.instIntCast (@Proximity.Row.coeff n r i)) (x i))

Proximity.Row.mk.inj.type:
∀ {n : Nat} {coeff : Fin n → Int} {rhs : Int} {coeff_1 : Fin n → Int} {rhs_1 : Int},
  @Eq.{1} (Proximity.Row n) (@Proximity.Row.mk n coeff rhs) (@Proximity.Row.mk n coeff_1 rhs_1) →
    And (@Eq.{1} (Fin n → Int) coeff coeff_1) (@Eq.{1} Int rhs rhs_1)

Proximity.Row.mk.injEq.type:
∀ {n : Nat} (coeff : Fin n → Int) (rhs : Int) (coeff_1 : Fin n → Int) (rhs_1 : Int),
  @Eq.{1} Prop (@Eq.{1} (Proximity.Row n) (@Proximity.Row.mk n coeff rhs) (@Proximity.Row.mk n coeff_1 rhs_1))
    (And (@Eq.{1} (Fin n → Int) coeff coeff_1) (@Eq.{1} Int rhs rhs_1))

